test('an apply refused because the source changed leads to the stale view: the old draft read-only, Discard completion kept and the latest Album offered', async () => {
  const state = { item: pairingReview() };
  const { writes } = route(state, (path, body) => {
    if (path.endsWith('/apply')) { state.item = { ...state.item, sourceStatus: 'changed', capabilities: { ...state.item.capabilities, apply: false } }; return reviewJson({ code: 'ADMIN_CATALOG_REVIEW_SOURCE_CHANGED' }, 409); }
    state.item = saved(state.item, body);
    return reviewJson({ item: state.item, receipt: state.item.receipts[0] });
  });
  mountPage();
  fireEvent.click(await readyUpdate('Update original Album (4)'));
  fireEvent.click(await screen.findByRole('button', { name: 'Confirm update (4)' }));
  const heading = await screen.findByRole('heading', { name: 'This completion is out of date' });
  await waitFor(() => expect(heading).toHaveFocus());
  expect(within(screen.getByText('View the old draft').closest('details')!).getByText('1-01 Synthetic opening (Live) · 1-1')).toBeInTheDocument();
  expect(screen.queryByRole('spinbutton')).not.toBeInTheDocument();
  expect(await screen.findByRole('button', { name: 'Discard completion' })).toBeEnabled();
  expect(screen.getByRole('link', { name: 'View the latest original Album' })).toHaveAttribute('href', `/admin/catalog/album/${albumId}`);
  expect(screen.queryByRole('button', { name: /^Update original Album|^Confirm update|Retry/ })).not.toBeInTheDocument();
  expect(writes.map(write => write.path)).toEqual([`/api/admin/v1/catalog-reviews/${reviewId}`, `/api/admin/v1/catalog-reviews/${reviewId}/apply`]);
});

describe('an update whose response was lost', () => {
  /** Prepares and confirms the pairing review's update, whose apply response is lost once; `after` answers every later apply. */
  async function lose(after: (state: { item: CatalogReview }, body: Record<string, unknown>) => Response) {
    const state = { item: pairingReview() }; let lost = false;
    const routed = route(state, (path, body) => {
      if (!path.endsWith('/apply')) { state.item = saved(state.item, body); return reviewJson({ item: state.item, receipt: state.item.receipts[0] }); }
      if (!lost) { lost = true; throw new TypeError('Synthetic lost response'); }
      return after(state, body);
    });
    mountPage();
    fireEvent.click(await readyUpdate('Update original Album (4)'));
    fireEvent.click(await screen.findByRole('button', { name: 'Confirm update (4)' }));
    const heading = await screen.findByRole('heading', { name: 'The result of this update is not confirmed yet' });
    return { state, heading, ...routed };
  }

  test('shows the unknown view with its frozen rows, and checking finds it applied by this operation, whose replayed receipt shows the applied view', async () => {
    const replay = vi.fn((state: { item: CatalogReview }) => reviewJson({ item: state.item, receipt: state.item.receipts[0] }));
    const { state, heading, writes } = await lose(replay);
    await waitFor(() => expect(heading).toHaveFocus());
    expect(screen.getByText('A lost connection does not mean the update failed. Check the result of this operation first.')).toBeVisible();
    expect(screen.getByText('This checks the same operation and never updates twice.')).toBeVisible();
    expect(screen.getByText('1-01 Synthetic opening (Live)').nextElementSibling).toHaveTextContent('Disc 1 · Track 1');
    // Nothing of the editing section shows, and the bar alone offers the next steps.
    expect(screen.queryByRole('region', { name: 'Check the suggested changes' })).not.toBeInTheDocument();
    expect(screen.getAllByRole('button', { name: /Retry/ }).map(button => button.textContent)).toEqual(['Retry the same operation']);
    // The server stored the apply: the read shows it applied by this operation.
    const apply = writes[1].body;
    state.item = applied(state.item, String(apply.operationId), apply.fields as ReviewField[]);
    fireEvent.click(screen.getByRole('button', { name: 'Check the result of this update' }));
    await waitFor(async () => expect(await screen.findByRole('heading', { name: '4 fields updated' })).toHaveFocus());
    expect(replay).toHaveBeenCalledTimes(1);
    expect(writes[2].body.operationId).toBe(apply.operationId);
  });

  test('checking finds it applied by another operation and shows the applied view without sending anything', async () => {
    const { state, writes } = await lose(() => reviewJson({ code: 'unexpected' }, 500));
    state.item = applied(state.item, '30000000-0000-4000-8000-000000000099', [{ scope: 'track', slotId, field: 'trackNumber' }]);
    fireEvent.click(screen.getByRole('button', { name: 'Check the result of this update' }));
    expect(await screen.findByRole('heading', { name: '1 field updated' })).toBeVisible();
    expect(writes).toHaveLength(2);
    expect(screen.queryByRole('button', { name: 'Retry original operation' })).not.toBeInTheDocument();
  });

  test('checking finds the source changed and shows the stale view without sending anything', async () => {
    const { state, writes } = await lose(() => reviewJson({ code: 'unexpected' }, 500));
    state.item = { ...state.item, sourceStatus: 'changed' };
    fireEvent.click(screen.getByRole('button', { name: 'Check the result of this update' }));
    expect(await screen.findByRole('heading', { name: 'This completion is out of date' })).toBeVisible();
    expect(writes).toHaveLength(2);
  });

  test('a refreshed read that finds the source changed settles it too: the stale view follows and Discard completion is available', async () => {
    const { state, writes } = await lose(() => reviewJson({ code: 'unexpected' }, 500));
    state.item = { ...state.item, sourceStatus: 'changed', capabilities: { ...state.item.capabilities, apply: false } };
    fireEvent.click(screen.getByRole('button', { name: 'Refresh status' }));
    expect(await screen.findByRole('heading', { name: 'This completion is out of date' })).toBeVisible();
    await waitFor(() => expect(screen.getByRole('button', { name: 'Discard completion' })).toBeEnabled());
    expect(screen.queryByRole('button', { name: /Check the result|Retry/ })).not.toBeInTheDocument();
    expect(writes).toHaveLength(2);
  });

  test('a review opened again with the update still unknown shows the unknown view and leaves the focus where it is', async () => {
    const { heading } = await lose(() => reviewJson({ code: 'unexpected' }, 500));
    await waitFor(() => expect(heading).toHaveFocus());
    cleanup(); mountPage();
    const reopened = await screen.findByRole('heading', { name: 'The result of this update is not confirmed yet' });
    expect(screen.getByText('1-01 Synthetic opening (Live)').nextElementSibling).toHaveTextContent('Disc 1 · Track 1');
    await screen.findByRole('button', { name: 'Check the result of this update' });
    expect(reopened).not.toHaveFocus();
    expect(document.body).toHaveFocus();
  });

  test('checking finds it still unapplied: the same operation may be sent again, and it applies once', async () => {
    const { writes } = await lose((state, body) => {
      state.item = applied(state.item, String(body.operationId), body.fields as ReviewField[]);
      return reviewJson({ item: state.item, receipt: state.item.receipts[0] });
    });
    fireEvent.click(screen.getByRole('button', { name: 'Check the result of this update' }));
    expect(await screen.findByText('The original Album is not updated yet. You can send the same operation again.')).toBeVisible();
    fireEvent.click(screen.getByRole('button', { name: 'Retry the same operation' }));
    await screen.findByRole('heading', { name: '4 fields updated' });
    expect(writes.slice(1).map(write => write.body.operationId)).toEqual([writes[1].body.operationId, writes[1].body.operationId]);
  });
});

test('losing the Admin view hides the bar with the review', async () => {
  route({ item: catalogReview() }, () => reviewJson({ code: 'unexpected' }, 500));
  mountPage();
  await screen.findByRole('region', { name: 'Current step' });
  act(() => adminWorkspace.select('user'));
  await waitFor(() => expect(screen.queryByRole('region', { name: 'Current step' })).not.toBeInTheDocument());
});
